    const far = haversine(gps, r);
    if (far > PIN_LIMIT_M) { toast(`Photo not used: you are ${fmtDist(far)} from ${recName(r)}. Take it within ${fmtDist(PIN_LIMIT_M)} of the pin.`, 6000); return; }
    prepImages(blob);
