      const nOpen = acc ? list.reduce((t, p) => t + openCount(p), 0) : 0;
      h.innerHTML = `<span class="ln">${C.xmlEsc(PLURAL[gname] || gname)}</span><span class="lc">${list.length}${acc ? ` · ${nOpen ? `${nOpen} open` : 'none open'}` : ''}</span>`;
