    const cid = `${uid()}${Math.random().toString(36).slice(2, 6)}`.replace(/[^A-Za-z0-9]/g, '').slice(0, 24);
    if (nm && (S.projects || []).includes(nm)) { S.meta = S.meta || {}; S.meta[nm] = { ...m, cid }; persist(); }
