  const chipName = (k) => (k.startsWith('ELEC:') ? `${k.slice(5)} poles` : k === 'ELEC' ? 'Electric poles' : k === 'GT' ? 'Globe poles' : k === '_none' ? 'Poles with no type' : k.startsWith('el:') ? (MARK_EL_NAME[k.slice(3)] || k.slice(3)).replace(/ \(.*\)$/, '') : `${ownName(k)} poles`);
