    S.prOpt = { per: $('prPer').value, num: $('prNum').value, by: $('prBy').value, loc: $('prLoc').value }; persist();
    const o = S.prOpt, NUM = o.num === 'plan' ? poleNums(projPoints(), routeModel()) : new Map();
