    const add = (item, size, forWhat, id, n) => { const k = [item, size, forWhat].join('|'), g = groups.get(k) || { item, size, forWhat, qty: 0, ids: [] }; g.qty += n || 1; if (id) g.ids.push(id); groups.set(k, g); }; // (v2.42.18: n each)
