        if (p.nap2 || p.nap2Id) { if (b.nap2Type === 'Dummy NAP') add('Dummy NAP', b.nap2Sz || 'size not set', b.nap2St || 'New', p.nap2Id || id); else add('NAP', b.nap2Type || 'NAP', b.nap2St || 'New', p.nap2Id || id); } // v2.42: its second box
