      const t = (Array.isArray(x.t) ? x.t : []).slice(0, 600).map((v) => s100(v, 60).trim()), keep = t.map((v, i) => (v ? i : -1)).filter((i) => i >= 0), al = (a, n) => (Array.isArray(a) ? keep.map((i) => s100(a[i], n).trim()) : null);
