      $('fxSub').textContent = `${I.length - open} of ${I.length} done${sent ? ` · ${sent} sent` : ''}`;
      H.push(`<div class="fx-bar" aria-hidden="true"><i style="width:${I.length ? Math.round(((I.length - open) / I.length) * 100) : 0}%"></i></div>`);
